import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.DFwwXrrM.js";const u=JSON.parse('{"title":"音乐库","description":"","frontmatter":{},"headers":[],"relativePath":"guide/library.md","filePath":"guide/library.md","lastUpdated":null}'),r={name:"guide/library.md"};function d(t,l,c,n,p,s){return i(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="音乐库" tabindex="-1">音乐库 <a class="header-anchor" href="#音乐库" aria-label="Permalink to &quot;音乐库&quot;">​</a></h1><p>Still 的音乐库围绕本地文件夹构建，不依赖云端账号或在线曲库。</p><h2 id="导入方式" tabindex="-1">导入方式 <a class="header-anchor" href="#导入方式" aria-label="Permalink to &quot;导入方式&quot;">​</a></h2><ul><li>选择一个本地音乐文件夹，Still 会递归扫描其中的音频文件</li><li>也可以从系统文件管理器拖入文件或文件夹</li><li>重复导入时会按本地路径合并曲目，避免同一文件重复出现</li></ul><h2 id="元数据" tabindex="-1">元数据 <a class="header-anchor" href="#元数据" aria-label="Permalink to &quot;元数据&quot;">​</a></h2><p>Still 会读取常见音频元数据：</p><ul><li>标题、艺术家、专辑、年份、曲目编号、时长</li><li>文件大小、创建时间、修改时间</li><li>音频格式、编码、码率、采样率、位深、声道</li><li>是否无损、标签类型</li></ul><p>读取失败时，Still 会回退到文件名和文件夹信息，保证曲目仍然可播放。</p><h2 id="封面" tabindex="-1">封面 <a class="header-anchor" href="#封面" aria-label="Permalink to &quot;封面&quot;">​</a></h2><p>封面来源按优先级处理：</p><ol><li>音频文件内嵌封面</li><li>文件夹中的常见封面文件</li><li>默认封面状态</li></ol><p>支持的文件夹封面名称包括：</p><ul><li><code>cover.jpg</code></li><li><code>cover.jpeg</code></li><li><code>cover.png</code></li><li><code>folder.jpg</code></li><li><code>folder.jpeg</code></li><li><code>folder.png</code></li><li><code>front.jpg</code></li><li><code>front.png</code></li><li><code>album.jpg</code></li><li><code>album.png</code></li><li><code>artwork.jpg</code></li><li><code>artwork.png</code></li></ul><h2 id="缓存与数据" tabindex="-1">缓存与数据 <a class="header-anchor" href="#缓存与数据" aria-label="Permalink to &quot;缓存与数据&quot;">​</a></h2><p>Still 会在 Electron 的 <code>userData</code> 目录保存本地状态和缓存：</p><ul><li><code>still-library.json</code>：音乐库、歌单、播放状态和偏好设置</li><li><code>still-metadata-cache.json</code>：音频元数据缓存</li><li><code>still-window-state.json</code>：桌面歌词窗口位置</li><li><code>cover-cache/</code>：封面缓存</li></ul><p>这些数据只存放在本机。</p><h2 id="歌单与队列" tabindex="-1">歌单与队列 <a class="header-anchor" href="#歌单与队列" aria-label="Permalink to &quot;歌单与队列&quot;">​</a></h2><ul><li>可以创建、重命名和删除歌单</li><li>可以把歌曲添加到歌单</li><li>支持从当前歌单移除歌曲</li><li>支持插播到队列末尾</li><li>支持拖拽调整播放队列顺序</li></ul>',19)])])}const _=e(r,[["render",d]]);export{u as __pageData,_ as default};
